"""Binary game-save format with integrity checking (CRC32).

Layout:
    magic    : 4 bytes, b'GSAV'
    version  : u8, must be 1
    pay_len  : u32 little-endian, byte length of payload
    payload  : pay_len bytes
        x      : f64 little-endian
        y      : f64 little-endian
        gold   : u32 little-endian
        nlen   : u16 little-endian, name byte length
        name   : nlen bytes, UTF-8 encoded
    crc32    : u32 little-endian, CRC-32 of all preceding bytes
"""

from __future__ import annotations

import struct
import zlib
from dataclasses import dataclass
from typing import Any

MAGIC = b"GSAV"
VERSION = 1

HEADER_FMT = "<4sBI"          # magic, version, payload length
HEADER_SIZE = struct.calcsize(HEADER_FMT)          # 9
PAYLOAD_FIXED_FMT = "<ddIH"       # x, y, gold, name length
PAYLOAD_FIXED_SIZE = struct.calcsize(PAYLOAD_FIXED_FMT)
CHECKSUM_SIZE = 4

MIN_SIZE = HEADER_SIZE + PAYLOAD_FIXED_SIZE + CHECKSUM_SIZE


class SaveFormatError(Exception):
    """Base class for all save-format errors."""


class StructuralError(SaveFormatError):
    """Malformed data: bad magic/version, truncation, inconsistent lengths."""


class ChecksumError(SaveFormatError):
    """Data parsed structurally but CRC32 does not match."""


@dataclass(frozen=True)
class Save:
    x: float
    y: float
    gold: int
    name: str


def encode(save: Any) -> bytes:
    """Serialize a Save into bytes."""
    name_bytes = save.name.encode("utf-8")
    if len(name_bytes) > 0xFFFF:
        raise ValueError("encoded name exceeds u16 length prefix")
    payload = struct.pack(
        PAYLOAD_FIXED_FMT, float(save.x), float(save.y), int(save.gold), len(name_bytes)
    ) + name_bytes
    header = struct.pack(HEADER_FMT, MAGIC, VERSION, len(payload))
    body = header + payload
    return body + struct.pack("<I", zlib.crc32(body))


def _unpack_payload(payload: bytes) -> Save:
    if len(payload) < PAYLOAD_FIXED_SIZE:
        raise StructuralError("payload shorter than fixed-size fields")
    x, y, gold, nlen = struct.unpack(PAYLOAD_FIXED_FMT, payload[:PAYLOAD_FIXED_SIZE])
    name_bytes = payload[PAYLOAD_FIXED_SIZE:]
    if len(name_bytes) != nlen:
        raise StructuralError(
            f"name length mismatch: prefix says {nlen}, payload has {len(name_bytes)}"
        )
    try:
        name = name_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise StructuralError(f"name is not valid UTF-8: {exc}") from exc
    return Save(x=x, y=y, gold=gold, name=name)


def decode(data: bytes) -> Save:
    """Parse bytes back into a Save. Raises StructuralError or ChecksumError."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise StructuralError("save data must be bytes-like")
    data = bytes(data)

    if len(data) < MIN_SIZE:
        raise StructuralError(
            f"file truncated: {len(data)} bytes, need at least {MIN_SIZE}"
        )

    magic, version, pay_len = struct.unpack(HEADER_FMT, data[:HEADER_SIZE])
    if magic != MAGIC:
        raise StructuralError(f"bad magic {magic!r}")
    if version != VERSION:
        raise StructuralError(f"unsupported version {version}")

    expected_total = HEADER_SIZE + pay_len + CHECKSUM_SIZE
    if len(data) < expected_total:
        raise StructuralError(
            f"file truncated: {len(data)} bytes, header declares {expected_total}"
        )
    if len(data) > expected_total:
        raise StructuralError(
            f"trailing garbage: expected {expected_total} bytes, got {len(data)}"
        )

    body = data[:-CHECKSUM_SIZE]
    (stored_crc,) = struct.unpack("<I", data[-CHECKSUM_SIZE:])
    actual_crc = zlib.crc32(body)
    if stored_crc != actual_crc:
        raise ChecksumError(
            f"CRC mismatch: stored 0x{stored_crc:08X}, computed 0x{actual_crc:08X}"
        )

    return _unpack_payload(body[HEADER_SIZE:HEADER_SIZE + pay_len])

